describe('Form Validation - Required Fields Highlighting', () => {
  beforeEach(() => {
    cy.visit('/form');
  });

  it('should highlight required fields with error messages when submitting an empty form', () => {
    // Attempt to submit the form without filling any fields
    cy.get('[data-testid="submit-button"]').click();

    // Verify that error messages appear for all required fields
    cy.get('[data-testid="name-error"]').should('be.visible').should('contain', 'Name is required');
    cy.get('[data-testid="email-error"]').should('be.visible').should('contain', 'Email is required');
    cy.get('[data-testid="password-error"]').should('be.visible').should('contain', 'Password is required');

    // Verify that the form was not submitted successfully
    cy.get('[data-testid="success-message"]').should('not.exist');
    cy.get('[data-testid="form-container"]').should('be.visible');

    // Verify that the error fields have focus or are visually marked
    cy.get('[data-testid="name-input"]').should('have.class', 'input-error');
    cy.get('[data-testid="email-input"]').should('have.class', 'input-error');
    cy.get('[data-testid="password-input"]').should('have.class', 'input-error');
  });

  it('should clear error messages and submit successfully when all required fields are filled', () => {
    // Fill in all required fields with valid data
    cy.get('[data-testid="name-input"]').type('John Doe');
    cy.get('[data-testid="email-input"]').type('john@example.com');
    cy.get('[data-testid="password-input"]').type('SecurePassword123');

    // Attempt to submit the form
    cy.get('[data-testid="submit-button"]').click();

    // Verify that error messages are no longer visible
    cy.get('[data-testid="name-error"]').should('not.exist');
    cy.get('[data-testid="email-error"]').should('not.exist');
    cy.get('[data-testid="password-error"]').should('not.exist');

    // Verify that the form was submitted successfully
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Form submitted successfully');
    cy.get('[data-testid="form-container"]').should('not.exist');
  });
});
